<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserConsentedScopes\Domain\ValueObject\Accessor\UserConsentedScopesDecisionAtAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserConsentedScopesDecisionAtAccessor trait.
 *
 * Covers null default, string/VO assignment via withDecisionAt,
 * getDecisionAt/decisionAt accessors, and isDecisionAtChanged with/without original.
 */
class UserConsentedScopesDecisionAtAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withDecisionAt creates a new instance with the DecisionAt set
     * from a string value, and getDecisionAt returns the primitive string.
     */
    public function testWithDecisionAtFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserConsentedScopesDecisionAtAccessorUnitTest();

        // Act
        $result = $holder->withDecisionAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->getDecisionAt());
    }
    /**
     * Asserts that withdecisionAt has access to the value object
     * from a string value, and getDecisionAt returns the primitive string.
     */
    public function testWithDecisionAtFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserConsentedScopesDecisionAtAccessorUnitTest();

        // Act
        $result = $holder->withDecisionAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->decisionAt()->value());
    }
    public function testChangedDecisionAt(): void
    {
        // Arrange
        $holder = new ImplWithUserConsentedScopesDecisionAtAccessorUnitTest();
        $original = $holder->withDecisionAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $same = $holder->withDecisionAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $modified = $holder->withDecisionAt((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')));

        // Act
        $unchanged = $holder->isDecisionAtChanged();
        $withSame = $original->isDecisionAtChanged($same);
        $withDiferent = $original->isDecisionAtChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserConsentedScopesDecisionAtAccessorUnitTest
{
    use UserConsentedScopesDecisionAtAccessor;
}
